   352→# ================================================================
   353→# 테스트 및 검증
   354→# ================================================================
   355→
   356→# 간단한 렉서 테스트
   357→fn testLexer(): string {
   358→  # 테스트 코드
   359→  testCases = [
   360→    "x = 42",
   361→    "print(x)",
   362→    "fn add(a, b) { return a + b }",
   363→    "if true { x = 1 }",
   364→    "str = \"hello\""
   365→  ]
   366→
   367→  i = 0
   368→  while i < len(testCases) {
   369→    code = testCases[i]
   370→    print("=" * 50)
   371→    print("Input: " + code)
   372→    print("-" * 50)
   373→
   374→    result = tokenize(code)
   375→
   376→    j = 0
   377→    while j < len(result) {
   378→      token = result[j]
   379→      print("  " + token["type"] + ": " + token["value"])
   380→      j = j + 1
   381→    }
   382→
   383→    i = i + 1
   384→  }
   385→}
