    14→# ================================================================
    15→# AST 노드 생성 함수들 (12+ 타입)
    16→# ================================================================
    17→
    18→# Statement 노드들
    19→fn createAssignment(variable: string, value: {}) {
    20→  return { "type": "assignment", "variable": variable, "value": value }
    21→}
    22→
    23→fn createFunctionDefinition(name: string, params: [], body: []) {
    24→  return { "type": "functionDefinition", "name": name, "params": params, "body": body }
    25→}
    26→
    27→fn createIfStatement(condition: {}, thenBranch: [], elseBranch: []) {
    28→  return { "type": "ifStatement", "condition": condition, "then": thenBranch, "else": elseBranch }
    29→}
    30→
    31→fn createWhileStatement(condition: {}, body: []) {
    32→  return { "type": "whileStatement", "condition": condition, "body": body }
    33→}
    34→
    35→fn createReturnStatement(value: {}) {
    36→  return { "type": "returnStatement", "value": value }
    37→}
    38→
    39→fn createBlockStatement(statements: []) {
    40→  return { "type": "blockStatement", "statements": statements }
    41→}
    42→
    43→# Expression 노드들
    44→fn createBinaryOp(left: {}, operator: string, right: {}) {
    45→  return { "type": "binaryOp", "left": left, "operator": operator, "right": right }
    46→}
    47→
    48→fn createUnaryOp(operator: string, operand: {}) {
    49→  return { "type": "unaryOp", "operator": operator, "operand": operand }
    50→}
    51→
    52→fn createCallExpression(callee: {}, args: []) {
    53→  return { "type": "call", "callee": callee, "arguments": args }
    54→}
    55→
    56→fn createIdentifier(name: string) {
    57→  return { "type": "identifier", "name": name }
    58→}
    59→
    60→fn createLiteral(value: {}, literalType: string) {
    61→  return { "type": "literal", "value": value, "literalType": literalType }
    62→}
    63→
    64→fn createArrayLiteral(elements: []) {
    65→  return { "type": "arrayLiteral", "elements": elements }
    66→}
    67→
    68→fn createArrayAccess(array: {}, index: {}) {
    69→  return { "type": "arrayAccess", "array": array, "index": index }
    70→}
    71→
    72→fn createArrayAssignment(array: {}, index: {}, value: {}) {
    73→  return { "type": "arrayAssignment", "array": array, "index": index, "value": value }
    74→}
    75→
    76→# ================================================================
    77→# Parser 상태 관리
    78→# ================================================================
    79→
    80→fn createParserState(tokens: []) {
    81→  return {
    82→    "tokens": tokens,
    83→    "position": 0
    84→  }
    85→}
    86→
    87→# 현재 토큰 접근
    88→fn currentToken(state: {}) {
    89→  if state["position"] < len(state["tokens"]) {
    90→    return state["tokens"][state["position"]]
    91→  }
    92→  return { "type": "eof", "value": "" }
    93→}
    94→
    95→# 다음 토큰 미리보기
    96→fn peekToken(state: {}, offset: int) {
    97→  pos = state["position"] + offset
    98→  if pos < len(state["tokens"]) {
    99→    return state["tokens"][pos]
   100→  }
   101→  return { "type": "eof", "value": "" }
   102→}
   103→
   104→# 토큰 이동
   105→fn advance(state: {}) {
   106→  state["position"] = state["position"] + 1
   107→  return state
   108→}
   109→
   110→# 토큰 매칭
   111→fn match(state: {}, expectedType: string, expectedValue: string) {
   112→  token = currentToken(state)
   113→  if token["type"] == expectedType and (expectedValue == "" or token["value"] == expectedValue) {
   114→    state = advance(state)
   115→    return { "matched": true, "state": state, "token": token }
   116→  }
   117→  return { "matched": false, "state": state, "token": null }
   118→}
   119→
   120→# ================================================================
   121→# Parse 진입점 (메인 함수)
   122→# ================================================================
   123→
   124→fn parse(tokens: []) {
   125→  state = createParserState(tokens)
   126→  statements = []
   127→
   128→  # 메인 루프: EOF까지 문장 파싱
   129→  while currentToken(state)["type"] != "eof" {
   130→    # 빈 줄 건너뛰기
   131→    if currentToken(state)["type"] == "newline" {
   132→      state = advance(state)
   133→    }
   134→    else {
   135→      stmt = parseStatement(state)
   136→      if stmt != null {
   137→        statements = statements + [stmt]
   138→      }
   139→      state = stmt["_state"]
   140→    }
   141→  }
   142→
   143→  return statements
   144→}
   145→
   146→# ================================================================
   147→# Statement 파싱
   148→# ================================================================
   149→
   150→fn parseStatement(state: {}) {
   151→  token = currentToken(state)
   152→
   153→  # 함수 정의
   154→  if token["type"] == "keyword" and token["value"] == "fn" {
   155→    return parseFunctionDefinition(state)
   156→  }
   157→  # if 문
   158→  else if token["type"] == "keyword" and token["value"] == "if" {
   159→    return parseIfStatement(state)
   160→  }
   161→  # while 루프
   162→  else if token["type"] == "keyword" and token["value"] == "while" {
   163→    return parseWhileStatement(state)
   164→  }
   165→  # return 문
   166→  else if token["type"] == "keyword" and token["value"] == "return" {
   167→    return parseReturnStatement(state)
   168→  }
   169→  # 블록
   170→  else if token["type"] == "lbrace" {
   171→    return parseBlockStatement(state)
   172→  }
   173→  # 식 문장
   174→  else {
   175→    return parseExpressionStatement(state)
   176→  }
   177→}
   178→
   179→# 식 문장
   180→fn parseExpressionStatement(state: {}) {
   181→  expr = parseExpression(state)
   182→  state = expr["_state"]
   183→
   184→  # 세미콜론 또는 줄바꿈 선택적
   185→  if currentToken(state)["type"] == "semicolon" {
   186→    state = advance(state)
   187→  }
   188→  else if currentToken(state)["type"] == "newline" {
   189→    state = advance(state)
   190→  }
   191→
   192→  return { "_state": state, "result": expr }
   193→}
   194→
   195→# 함수 정의
   196→fn parseFunctionDefinition(state: {}) {
   197→  # fn 키워드 건너뛰기
   198→  state = advance(state)
   199→
   200→  # 함수 이름
   201→  nameToken = currentToken(state)
   202→  if nameToken["type"] != "identifier" {
   203→    print("Expected identifier after 'fn'")
   204→    return { "_state": state, "result": null }
   205→  }
   206→  funcName = nameToken["value"]
   207→  state = advance(state)
   208→
   209→  # 매개변수 목록
   210→  params = []
   211→  if currentToken(state)["type"] == "lparen" {
   212→    state = advance(state)
   213→
   214→    while currentToken(state)["type"] != "rparen" {
   215→      paramToken = currentToken(state)
   216→      if paramToken["type"] == "identifier" {
   217→        params = params + [paramToken["value"]]
   218→        state = advance(state)
   219→
   220→        # 타입 주석 건너뛰기 (optional)
   221→        if currentToken(state)["type"] == "colon" {
   222→          state = advance(state)
   223→          # 타입 정보 무시
   224→          state = advance(state)
   225→        }
   226→
   227→        # 쉼표
   228→        if currentToken(state)["type"] == "comma" {
   229→          state = advance(state)
   230→        }
   231→      }
   232→      else {
   233→        print("Expected parameter name")
   234→        state = advance(state)
   235→      }
   236→    }
   237→
   238→    state = advance(state)  # rparen
   239→  }
   240→
   241→  # 함수 본문
   242→  body = []
   243→  if currentToken(state)["type"] == "lbrace" {
   244→    blockStmt = parseBlockStatement(state)
   245→    state = blockStmt["_state"]
   246→    body = blockStmt["result"]["statements"]
   247→  }
   248→
   249→  funcDef = createFunctionDefinition(funcName, params, body)
   250→  return { "_state": state, "result": funcDef }
   251→}
   252→
   253→# if 문
   254→fn parseIfStatement(state: {}) {
   255→  # if 키워드 건너뛰기
   256→  state = advance(state)
   257→
   258→  # 조건
   259→  condition = parseExpression(state)
   260→  state = condition["_state"]
   261→
   262→  # then 블록
   263→  thenBlock = parseBlockStatement(state)
   264→  state = thenBlock["_state"]
   265→  thenBranch = thenBlock["result"]["statements"]
   266→
   267→  # else 블록 (optional)
   268→  elseBranch = []
   269→  if currentToken(state)["type"] == "keyword" and currentToken(state)["value"] == "else" {
   270→    state = advance(state)
   271→
   272→    elseBlock = parseBlockStatement(state)
   273→    state = elseBlock["_state"]
   274→    elseBranch = elseBlock["result"]["statements"]
   275→  }
   276→
   277→  ifStmt = createIfStatement(condition, thenBranch, elseBranch)
   278→  return { "_state": state, "result": ifStmt }
   279→}
   280→
   281→# while 루프
   282→fn parseWhileStatement(state: {}) {
   283→  # while 키워드 건너뛰기
   284→  state = advance(state)
   285→
   286→  # 조건
   287→  condition = parseExpression(state)
   288→  state = condition["_state"]
   289→
   290→  # 루프 본문
   291→  body = []
   292→  if currentToken(state)["type"] == "lbrace" {
   293→    blockStmt = parseBlockStatement(state)
   294→    state = blockStmt["_state"]
   295→    body = blockStmt["result"]["statements"]
   296→  }
   297→
   298→  whileStmt = createWhileStatement(condition, body)
   299→  return { "_state": state, "result": whileStmt }
   300→}
   301→
   302→# return 문
   303→fn parseReturnStatement(state: {}) {
   304→  # return 키워드 건너뛰기
   305→  state = advance(state)
   306→
   307→  # 반환값 (optional)
   308→  value = null
   309→  if currentToken(state)["type"] != "newline" and currentToken(state)["type"] != "eof" {
   310→    exprResult = parseExpression(state)
   311→    state = exprResult["_state"]
   312→    value = exprResult
   313→  }
   314→
   315→  retStmt = createReturnStatement(value)
   316→  return { "_state": state, "result": retStmt }
   317→}
   318→
   319→# 블록 문
   320→fn parseBlockStatement(state: {}) {
   321→  if currentToken(state)["type"] != "lbrace" {
   322→    print("Expected '{'")
   323→    return { "_state": state, "result": { "type": "blockStatement", "statements": [] } }
   324→  }
   325→
   326→  state = advance(state)  # lbrace
   327→  statements = []
   328→
   329→  while currentToken(state)["type"] != "rbrace" and currentToken(state)["type"] != "eof" {
   330→    if currentToken(state)["type"] == "newline" {
   331→      state = advance(state)
   332→    }
   333→    else {
   334→      stmt = parseStatement(state)
   335→      if stmt != null {
   336→        statements = statements + [stmt["result"]]
   337→      }
   338→      state = stmt["_state"]
   339→    }
   340→  }
   341→
   342→  if currentToken(state)["type"] == "rbrace" {
   343→    state = advance(state)
   344→  }
   345→
   346→  blockStmt = createBlockStatement(statements)
   347→  return { "_state": state, "result": blockStmt }
   348→}
   349→
   350→# ================================================================
   351→# Expression 파싱 (우선순위 기반)
   352→# ================================================================
   353→
   354→# 최상위 (낮은 우선순위)
   355→fn parseExpression(state: {}) {
   356→  return parseAssignment(state)
   357→}
   358→
   359→# 할당 (= 연산자)
   360→fn parseAssignment(state: {}) {
   361→  expr = parseOr(state)
   362→  state = expr["_state"]
   363→
   364→  if currentToken(state)["type"] == "equals" {
   365→    state = advance(state)
   366→
   367→    # 좌변이 identifier 또는 arrayAccess
   368→    if expr["type"] == "identifier" {
   369→      value = parseAssignment(state)
   370→      state = value["_state"]
   371→
   372→      assignment = createAssignment(expr["name"], value)
   373→      return { "_state": state, "result": assignment }
   374→    }
   375→    else if expr["type"] == "arrayAccess" {
   376→      value = parseAssignment(state)
   377→      state = value["_state"]
   378→
   379→      assignment = createArrayAssignment(expr["array"], expr["index"], value)
   380→      return { "_state": state, "result": assignment }
   381→    }
   382→  }
   383→
   384→  return { "_state": state, "result": expr }
   385→}
   386→
   387→# OR 연산자 (||)
   388→fn parseOr(state: {}) {
   389→  left = parseAnd(state)
   390→  state = left["_state"]
   391→
   392→  while currentToken(state)["type"] == "operator" and currentToken(state)["value"] == "||" {
   393→    state = advance(state)
   394→    right = parseAnd(state)
   395→    state = right["_state"]
   396→
   397→    left = createBinaryOp(left, "||", right)
   398→  }
   399→
   400→  return { "_state": state, "result": left }
   401→}
   402→
   403→# AND 연산자 (&&)
   404→fn parseAnd(state: {}) {
   405→  left = parseEquality(state)
   406→  state = left["_state"]
   407→
   408→  while currentToken(state)["type"] == "operator" and currentToken(state)["value"] == "&&" {
   409→    state = advance(state)
   410→    right = parseEquality(state)
   411→    state = right["_state"]
   412→
   413→    left = createBinaryOp(left, "&&", right)
   414→  }
   415→
   416→  return { "_state": state, "result": left }
   417→}
   418→
   419→# 동등성 (==, !=)
   420→fn parseEquality(state: {}) {
   421→  left = parseComparison(state)
   422→  state = left["_state"]
   423→
   424→  while currentToken(state)["type"] == "operator" and
   425→        (currentToken(state)["value"] == "==" or currentToken(state)["value"] == "!=") {
   426→    op = currentToken(state)["value"]
   427→    state = advance(state)
   428→
   429→    right = parseComparison(state)
   430→    state = right["_state"]
   431→
   432→    left = createBinaryOp(left, op, right)
   433→  }
   434→
   435→  return { "_state": state, "result": left }
   436→}
   437→
   438→# 비교 (<, <=, >, >=)
   439→fn parseComparison(state: {}) {
   440→  left = parseAddition(state)
   441→  state = left["_state"]
   442→
   443→  while currentToken(state)["type"] == "operator" and
   444→        (currentToken(state)["value"] == "<" or
   445→         currentToken(state)["value"] == "<=" or
   446→         currentToken(state)["value"] == ">" or
   447→         currentToken(state)["value"] == ">=") {
   448→    op = currentToken(state)["value"]
   449→    state = advance(state)
   450→
   451→    right = parseAddition(state)
   452→    state = right["_state"]
   453→
   454→    left = createBinaryOp(left, op, right)
   455→  }
   456→
   457→  return { "_state": state, "result": left }
   458→}
   459→
   460→# 덧셈 (+, -)
   461→fn parseAddition(state: {}) {
   462→  left = parseMultiplication(state)
   463→  state = left["_state"]
   464→
   465→  while currentToken(state)["type"] == "operator" and
   466→        (currentToken(state)["value"] == "+" or currentToken(state)["value"] == "-") {
   467→    op = currentToken(state)["value"]
   468→    state = advance(state)
   469→
   470→    right = parseMultiplication(state)
   471→    state = right["_state"]
   472→
   473→    left = createBinaryOp(left, op, right)
   474→  }
   475→
   476→  return { "_state": state, "result": left }
   477→}
   478→
   479→# 곱셈 (*, /, %)
   480→fn parseMultiplication(state: {}) {
   481→  left = parseUnary(state)
   482→  state = left["_state"]
   483→
   484→  while currentToken(state)["type"] == "operator" and
   485→        (currentToken(state)["value"] == "*" or
   486→         currentToken(state)["value"] == "/" or
   487→         currentToken(state)["value"] == "%") {
   488→    op = currentToken(state)["value"]
   489→    state = advance(state)
   490→
   491→    right = parseUnary(state)
   492→    state = right["_state"]
   493→
   494→    left = createBinaryOp(left, op, right)
   495→  }
   496→
   497→  return { "_state": state, "result": left }
   498→}
   499→
   500→# 단항 연산 (-, !, &, &mut)
   501→fn parseUnary(state: {}) {
   502→  if currentToken(state)["type"] == "operator" and
   503→     (currentToken(state)["value"] == "-" or
   504→      currentToken(state)["value"] == "!" or
   505→      currentToken(state)["value"] == "&") {
   506→    op = currentToken(state)["value"]
   507→    state = advance(state)
   508→
   509→    # &mut 처리
   510→    if op == "&" and currentToken(state)["type"] == "keyword" and currentToken(state)["value"] == "mut" {
   511→      state = advance(state)
   512→      op = "&mut"
   513→    }
   514→
   515→    operand = parseUnary(state)
   516→    state = operand["_state"]
   517→
   518→    unary = createUnaryOp(op, operand)
   519→    return { "_state": state, "result": unary }
   520→  }
   521→
   522→  return parseCall(state)
   523→}
   524→
   525→# 함수 호출 (())
   526→fn parseCall(state: {}) {
   527→  expr = parsePrimary(state)
   528→  state = expr["_state"]
   529→
   530→  while true {
   531→    if currentToken(state)["type"] == "lparen" {
   532→      # 함수 호출
   533→      state = advance(state)
   534→      args = []
   535→
   536→      while currentToken(state)["type"] != "rparen" {
   537→        arg = parseExpression(state)
   538→        state = arg["_state"]
   539→        args = args + [arg]
   540→
   541→        if currentToken(state)["type"] == "comma" {
   542→          state = advance(state)
   543→        }
   544→      }
   545→
   546→      state = advance(state)  # rparen
   547→      expr = createCallExpression(expr, args)
   548→    }
   549→    else if currentToken(state)["type"] == "lbracket" {
   550→      # 배열 접근 ([])
   551→      state = advance(state)
   552→      index = parseExpression(state)
   553→      state = index["_state"]
   554→
   555→      if currentToken(state)["type"] == "rbracket" {
   556→        state = advance(state)
   557→      }
   558→
   559→      expr = createArrayAccess(expr, index)
   560→    }
   561→    else {
   562→      break
   563→    }
   564→  }
   565→
   566→  return { "_state": state, "result": expr }
   567→}
   568→
   569→# 기본 표현식
   570→fn parsePrimary(state: {}) {
   571→  token = currentToken(state)
   572→
   573→  # 숫자
   574→  if token["type"] == "number" {
   575→    state = advance(state)
   576→    return { "_state": state, "result": createLiteral(token["value"], "number") }
   577→  }
   578→  # 문자열
   579→  else if token["type"] == "string" {
   580→    state = advance(state)
   581→    return { "_state": state, "result": createLiteral(token["value"], "string") }
   582→  }
   583→  # true, false
   584→  else if token["type"] == "keyword" and (token["value"] == "true" or token["value"] == "false") {
   585→    state = advance(state)
   586→    return { "_state": state, "result": createLiteral(token["value"], "boolean") }
   587→  }
   588→  # null
   589→  else if token["type"] == "keyword" and token["value"] == "null" {
   590→    state = advance(state)
   591→    return { "_state": state, "result": createLiteral(null, "null") }
   592→  }
   593→  # 배열 리터럴 ([])
   594→  else if token["type"] == "lbracket" {
   595→    state = advance(state)
   596→    elements = []
   597→
   598→    while currentToken(state)["type"] != "rbracket" {
   599→      elem = parseExpression(state)
   600→      state = elem["_state"]
   601→      elements = elements + [elem]
   602→
   603→      if currentToken(state)["type"] == "comma" {
   604→        state = advance(state)
   605→      }
   606→    }
   607→
   608→    state = advance(state)  # rbracket
   609→    return { "_state": state, "result": createArrayLiteral(elements) }
   610→  }
   611→  # 괄호 표현식
   612→  else if token["type"] == "lparen" {
   613→    state = advance(state)
   614→    expr = parseExpression(state)
   615→    state = expr["_state"]
   616→
   617→    if currentToken(state)["type"] == "rparen" {
   618→      state = advance(state)
   619→    }
   620→
   621→    return { "_state": state, "result": expr }
   622→  }
   623→  # 식별자
   624→  else if token["type"] == "identifier" {
   625→    state = advance(state)
   626→    return { "_state": state, "result": createIdentifier(token["value"]) }
   627→  }
   628→  else {
   629→    print("Unexpected token: " + token["type"])
   630→    return { "_state": state, "result": null }
   631→  }
   632→}
