    14→/// x86-64 일반 목적 레지스터
    15→pub struct GeneralPurposeRegisters {
    16→    /// RAX: 누적기
    17→    pub rax: u64,
    18→    /// RBX: 기본
    19→    pub rbx: u64,
    20→    /// RCX: 카운터
    21→    pub rcx: u64,
    22→    /// RDX: 데이터
    23→    pub rdx: u64,
