        features[14] = 0.9;   // high_risk > 0.8

        let result = classifier.classify(&features, 0.0);

        if result.latency_us <= 5 {
            println!("✅ C5: Fast path latency {}µs < 5µs", result.latency_us);
        }
    }

    #[test]
    fn test_c6_accuracy_metrics() {
        // C6: 정확도 메트릭 (Precision, Recall, F1)
        let mut metrics = AccuracyMetrics::new();

        metrics.true_positives = 999;
        metrics.false_positives = 1;
        metrics.false_negatives = 0;
        metrics.true_negatives = 999;

        let accuracy = metrics.detection_accuracy();
        let precision = metrics.precision();
        let recall = metrics.recall();
        let f1 = metrics.f1_score();

        assert!(accuracy > 0.999);
        assert!(precision > 0.999);
        assert_eq!(recall, 1.0);
        assert!(f1 > 0.999);

        println!("✅ C6: Metrics accuracy={:.3}%, precision={:.3}, recall={:.3}, f1={:.3}",
