    last_decision: Option<ControlDecision>,
}

#[derive(Clone, Debug)]
pub struct ResponseRecord {
    pub pid: u32,
    pub action: String,
    pub timestamp: u64,
    pub success: bool,
    pub confidence: f64,
}

impl ResponseEngine {
    pub fn new() -> Self {
        let mut threat_policies = HashMap::new();

        // 각 위협 유형별 정책
        threat_policies.insert(
            "ZeroDay".to_string(),
            SecurityPolicy::ConfidenceThreshold(0.85),
