            duration_ns: 500,
            timestamp: 1000,
            args: vec![],
        });

        // 2단계: Write (syscall 1)
        syscall_sequence.push(RealEvent {
            pid: 1001,
            syscall_id: 1,   // write
            duration_ns: 1200,
            timestamp: 2000,
            args: vec![1024],  // 1KB write
