// Phase 6 Day 5-6: Model Evaluation & Drift Detection
// Model drift detection 및 성능 모니터링
// ~300줄

use std::collections::VecDeque;

pub use super::gradient_descent::NeuralNetworkWeights;
pub use super::online_learning_pipeline::TrainingSample;

// ========== Core Structures ==========

pub struct PerformanceMetrics {
    pub precision: f64,
    pub recall: f64,
    pub f1_score: f64,
    pub accuracy: f64,
    pub auc_roc: f64,
}

impl PerformanceMetrics {
    pub fn new() -> Self {
        Self {
            precision: 0.0,
            recall: 0.0,
            f1_score: 0.0,
            accuracy: 0.0,
            auc_roc: 0.0,
        }
    }
}

pub struct DriftDetectionResult {
    pub is_drifting: bool,
    pub kl_divergence: f64,
    pub affected_classes: Vec<u32>,
    pub severity: f64,
    pub recommendation: String,
}

pub struct ModelEvaluator {
    pub validation_set: Vec<TrainingSample>,
    pub test_set: Vec<TrainingSample>,
    pub baseline_distribution: Vec<f64>,
    pub current_distribution: Vec<f64>,
    pub kl_divergence_threshold: f64,
    pub drift_history: VecDeque<f64>,
    pub performance_history: VecDeque<PerformanceMetrics>,
}

impl ModelEvaluator {
    pub fn new() -> Self {
        // 초기 분포: 균등 분포 (8가지 위협 타입)
        let baseline = vec![1.0 / 8.0; 8];

        Self {
            validation_set: Vec::new(),
            test_set: Vec::new(),
            baseline_distribution: baseline.clone(),
            current_distribution: baseline,
            kl_divergence_threshold: 0.2,
            drift_history: VecDeque::new(),
            performance_history: VecDeque::new(),
        }
    }

    pub fn add_validation_sample(&mut self, sample: TrainingSample) {
        self.validation_set.push(sample);
        if self.validation_set.len() > 1000 {
            self.validation_set.remove(0);
        }
    }

    pub fn add_test_sample(&mut self, sample: TrainingSample) {
        self.test_set.push(sample);
        if self.test_set.len() > 5000 {
            self.test_set.remove(0);
        }
    }
}

// ========== Evaluation Functions ==========

pub fn softmax(logits: &[f64]) -> Vec<f64> {
    let max = logits.iter().fold(f64::NEG_INFINITY, |a, &b| a.max(b));
    let exp_vals: Vec<f64> = logits.iter().map(|x| (x - max).exp()).collect();
    let sum: f64 = exp_vals.iter().sum();
    exp_vals.iter().map(|x| x / sum).collect()
}

pub fn get_predicted_class(prediction: &[f64]) -> u32 {
    prediction
        .iter()
        .enumerate()
        .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
        .map(|(idx, _)| idx as u32)
        .unwrap_or(0)
}

impl ModelEvaluator {
    pub fn evaluate_on_validation_set(&mut self) -> PerformanceMetrics {
        if self.validation_set.is_empty() {
            return PerformanceMetrics::new();
        }

        let mut tp = vec![0; 8];
        let mut fp = vec![0; 8];
        let mut fn_count = vec![0; 8];
        let mut tn = vec![0; 8];

        for sample in &self.validation_set {
            let true_label = sample.label as usize;

            // Mock prediction: confidence로 결정
            let predicted_label = if sample.confidence > 0.7 {
                true_label
            } else {
                (true_label + 1) % 8
            };

            if predicted_label == true_label {
                tp[true_label] += 1;
            } else {
                fp[predicted_label] += 1;
                fn_count[true_label] += 1;
            }
        }

        // 정확도 계산
        let total_correct: i32 = tp.iter().sum();
        let accuracy = total_correct as f64 / self.validation_set.len() as f64;

        // 정밀도 계산
        let mut precisions = Vec::new();
        for i in 0..8 {
            let precision = if tp[i] + fp[i] > 0 {
                tp[i] as f64 / (tp[i] + fp[i]) as f64
            } else {
                1.0
            };
            precisions.push(precision);
        }
        let precision = precisions.iter().sum::<f64>() / 8.0;

        // 재현율 계산
        let mut recalls = Vec::new();
        for i in 0..8 {
            let recall = if tp[i] + fn_count[i] > 0 {
                tp[i] as f64 / (tp[i] + fn_count[i]) as f64
            } else {
                1.0
            };
            recalls.push(recall);
        }
        let recall = recalls.iter().sum::<f64>() / 8.0;

        // F1 점수
        let f1_score = if precision + recall > 0.0 {
            2.0 * precision * recall / (precision + recall)
        } else {
            0.0
        };

        let metrics = PerformanceMetrics {
            precision,
            recall,
            f1_score,
            accuracy,
            auc_roc: 0.99,  // Mock: 높은 AUC
        };

        self.performance_history.push_back(metrics.clone());
        if self.performance_history.len() > 100 {
            self.performance_history.pop_front();
        }

        // 메트릭 구조체의 필드를 직접 복사하여 반환
        PerformanceMetrics {
            precision: metrics.precision,
            recall: metrics.recall,
            f1_score: metrics.f1_score,
            accuracy: metrics.accuracy,
            auc_roc: metrics.auc_roc,
        }
    }

    pub fn compute_kl_divergence(&mut self) -> f64 {
        // 현재 분포 업데이트
        if !self.validation_set.is_empty() {
            let mut class_counts = vec![0; 8];
            for sample in &self.validation_set {
                if (sample.label as usize) < 8 {
                    class_counts[sample.label as usize] += 1;
                }
            }

            for i in 0..8 {
                self.current_distribution[i] =
                    (class_counts[i] as f64) / self.validation_set.len() as f64;
            }
        }

        // KL divergence 계산: KL(P||Q) = Σ P(i) * log(P(i) / Q(i))
        let mut kl = 0.0;
        for i in 0..8 {
            if self.baseline_distribution[i] > 0.0 && self.current_distribution[i] > 0.0 {
                let ratio = self.baseline_distribution[i] / self.current_distribution[i];
                kl += self.baseline_distribution[i] * ratio.ln();
            }
        }

        kl
    }

    pub fn detect_drift(&mut self) -> DriftDetectionResult {
        let kl = self.compute_kl_divergence();

        // KL 이력 저장
        self.drift_history.push_back(kl);
        if self.drift_history.len() > 100 {
            self.drift_history.pop_front();
        }

        let is_drifting = kl > self.kl_divergence_threshold;

        // 영향받은 클래스 식별
        let mut affected_classes = Vec::new();
        for i in 0..8 {
            let change = (self.current_distribution[i] - self.baseline_distribution[i]).abs();
            if change > 0.05 {  // 5% 이상 변화
                affected_classes.push(i as u32);
            }
        }

        // 심각도 계산
        let severity = if kl >= self.kl_divergence_threshold {
            ((kl - self.kl_divergence_threshold) / 0.1).min(1.0)
        } else {
            0.0
        };

        // 권장사항
        let recommendation = if is_drifting {
            format!(
                "Drift detected: KL={:.3}, increase training data for classes: {:?}",
                kl, affected_classes
            )
        } else {
            "Model distribution stable".to_string()
        };

        DriftDetectionResult {
            is_drifting,
            kl_divergence: kl,
            affected_classes,
            severity,
            recommendation,
        }
    }

    pub fn compare_model_versions(
        &self,
        old_weights: &NeuralNetworkWeights,
        new_weights: &NeuralNetworkWeights,
    ) -> f64 {
        // 가중치 변화 측정
        let mut total_change = 0.0;
        let mut total_weight = 0.0;

        for i in 0..old_weights.weights_l1.len() {
            let change = (new_weights.weights_l1[i] - old_weights.weights_l1[i]).abs();
            total_change += change;
            total_weight += old_weights.weights_l1[i].abs() + 1e-9;
        }

        for i in 0..old_weights.weights_l2.len() {
            let change = (new_weights.weights_l2[i] - old_weights.weights_l2[i]).abs();
            total_change += change;
            total_weight += old_weights.weights_l2[i].abs() + 1e-9;
        }

        for i in 0..old_weights.weights_l3.len() {
            let change = (new_weights.weights_l3[i] - old_weights.weights_l3[i]).abs();
            total_change += change;
            total_weight += old_weights.weights_l3[i].abs() + 1e-9;
        }

        total_change / total_weight
    }

    pub fn get_class_distribution(&self, predictions: &[Vec<f64>]) -> Vec<f64> {
        let mut distribution = vec![0.0; 8];

        for pred in predictions {
            for i in 0..8 {
                distribution[i] += pred[i];
            }
        }

        for i in 0..8 {
            distribution[i] /= predictions.len() as f64;
        }

        distribution
    }

    pub fn get_drift_history(&self) -> Vec<f64> {
        self.drift_history.iter().copied().collect()
    }
}

// ========== Tests (C1-C6) ==========

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_c1_validation_evaluation() {
        let mut evaluator = ModelEvaluator::new();

        for i in 0..100 {
            let sample = TrainingSample {
                features: vec![0.1; 16],
                label: (i % 8) as u32,
                confidence: 0.8,
                timestamp_ns: 1000 + i as u64,
            };
            evaluator.add_validation_sample(sample);
        }

        let metrics = evaluator.evaluate_on_validation_set();
        assert!(metrics.accuracy > 0.7);
    }

    #[test]
    fn test_c2_kl_divergence() {
        let mut evaluator = ModelEvaluator::new();

        for i in 0..100 {
            let sample = TrainingSample {
                features: vec![0.1; 16],
                label: (i % 8) as u32,
                confidence: 0.8,
                timestamp_ns: 1000 + i as u64,
            };
            evaluator.add_validation_sample(sample);
        }

        let kl = evaluator.compute_kl_divergence();
        assert!(kl >= 0.0);
    }

    #[test]
    fn test_c3_drift_detection() {
        let mut evaluator = ModelEvaluator::new();

        // 균등 분포 (드리프트 없음)
        for i in 0..80 {
            let sample = TrainingSample {
                features: vec![0.1; 16],
                label: (i % 8) as u32,
                confidence: 0.8,
                timestamp_ns: 1000 + i as u64,
            };
            evaluator.add_validation_sample(sample);
        }

        let result = evaluator.detect_drift();
        assert!(!result.is_drifting);
    }

    #[test]
    fn test_c4_model_version_comparison() {
        let evaluator = ModelEvaluator::new();
        let old_weights = NeuralNetworkWeights::new();
        let mut new_weights = NeuralNetworkWeights::new();

        // 가중치 약간 변경
