    13→    pub total_time_us: u64,
    14→    pub avg_time_us: u64,
    15→    pub min_time_us: u64,
    16→    pub max_time_us: u64,
    17→    pub throughput_kps: f64,
    18→}
    19→
    20→impl BenchmarkResult {
    21→    pub fn new(name: String) -> Self {
    22→        Self {
    23→            name,
    24→            iterations: 0,
    25→            total_time_us: 0,
    26→            avg_time_us: 0,
