    32→
    33→    pub fn record_iteration(&mut self, duration_us: u64) {
    34→        self.iterations += 1;
    35→        self.total_time_us += duration_us;
    36→        self.min_time_us = self.min_time_us.min(duration_us);
    37→        self.max_time_us = self.max_time_us.max(duration_us);
    38→
    39→        self.avg_time_us = self.total_time_us / self.iterations as u64;
    40→
    41→        if duration_us > 0 {
    42→            self.throughput_kps = (1000.0 * 1000.0) / (duration_us as f64);
    43→        }
    44→    }
    45→
    46→    pub fn p99_latency_us(&self) -> u64 {
    47→        // Estimate P99 as max_time_us
    48→        self.max_time_us
    49→    }
    50→
    51→    pub fn is_within_budget(&self, budget_us: u64) -> bool {
    52→        self.avg_time_us <= budget_us
    53→    }
    54→}
